      "footer": "\u003cnav class=\"page-end\" aria-label=\"Page links\">\u003ca data-page-link href=\"index.html\">Home\u003c/a> \u003ca data-page-link href=\"start--what-is-hlc.html\">What is HLC?\u003c/a> \u003ca data-page-link href=\"foundations--cultural-hologram.html\">The cultural hologram\u003c/a> \u003ca data-page-link href=\"foundations--digital-trace.html\">The digital trace\u003c/a> \u003ca data-page-link href=\"foundations--latent-manifold.html\">The latent manifold\u003c/a> \u003ca data-page-link href=\"foundations--activation-field.html\">The activation field\u003c/a> \u003ca data-page-link href=\"practice--epistemic-posture.html\">Epistemic posture\u003c/a> \u003ca data-page-link href=\"practice--telescope-protocol.html\">A small telescope protocol\u003c/a> \u003ca data-page-link href=\"practice--exercises--attractor-survey.html\">Exercise: survey the familiar answers\u003c/a> \u003ca data-page-link href=\"practice--exercises--boundary-search.html\">Exercise: search a boundary\u003c/a> \u003ca data-page-link href=\"practice--exercises--integration.html\">Integration: bring an idea back\u003c/a> \u003ca data-page-link href=\"critique--persona.html\">Persona and the feeling of an interlocutor\u003c/a> \u003ca data-page-link href=\"critique--novelty-and-evidence.html\">Novelty needs evidence\u003c/a> \u003ca data-page-link href=\"critique--recursive-loops.html\">When reflection becomes a loop\u003c/a> \u003ca data-page-link href=\"critique--ideology-and-power.html\">Ideology and the shape of what is easy to say\u003c/a> \u003ca data-page-link href=\"critique--technosolutionism.html\">Can a telescope become a solution?\u003c/a>\u003c/nav>"
